"""Prepare peptide sequences, flanking residues, and alleles for MHCflurry."""

import os
import pandas as pd

PROTEIN_SEQS = {
    "PRAME": "",
    "WT1": "",
    "CCNA1": "",
    "HOXA9": "MATTGALGNYYVDSFLLGADAADELSVGRYAPGTLGQPPRQAATLAEHPDFSPCSFQSKATVFGASWNPVHAAGANAVPAAVYHHHHHHPYVHPQAPVAAAAPDGRYMRSWLEPTPGALSFAGLPSSRPYGIKPEPLSARRGDCPTLDTHTLSLTDYACGSPPVDREKQPSEGAFSENNAENESGGDKPPIDPNNPAANWLHARSTRKKRCPYTKHQTLELEKEFLFNMYLTRDRRYEVARLLNLTERQVKIWFQNRRMKMKKINKDRAKDE",
}

FLANK_LEN = 10

def get_flanks(protein, start, end):
    """start/end are 1-based inclusive, matching cleaned_mhc.csv convention."""
    seq = PROTEIN_SEQS[protein]
    n_flank = seq[max(0, start - 1 - FLANK_LEN):start - 1]
    c_flank = seq[end:end + FLANK_LEN]
    return n_flank, c_flank

os.makedirs("data/raw/mhcflurry", exist_ok=True)

df = pd.read_csv("data/processed/mhc_cleavage.csv")

flanks = df.apply(lambda r: get_flanks(r["protein"], r["start"], r["end"]), axis=1)
df["n_flank"] = [f[0] for f in flanks]
df["c_flank"] = [f[1] for f in flanks]

# MHCflurry allele format needs no asterisk/colon: HLA-A*02:01 -> HLA-A0201
df["mhcflurry_allele"] = df["allele"].str.replace("*", "").str.replace(":", "")

out = df[["peptide", "mhcflurry_allele", "n_flank", "c_flank", "protein", "start", "end"]].rename(
    columns={"mhcflurry_allele": "allele"}
)
out.to_csv("data/raw/mhcflurry/mhcflurry_input.csv", index=False)
print(f"Wrote {len(out)} rows to data/raw/mhcflurry/mhcflurry_input.csv")